    32  class RLEData : public QVector<uchar>
    33  {
    34  public:
    35      RLEData() {}
    36      RLEData(const uchar *d, uint l, uint o) : _offset(o)
    37      {
    38          for (uint i = 0; i < l; i++) {
    39              append(d[i]);
    40          }
    41      }
    42      bool operator<(const RLEData &) const;
    43      void write(QDataStream &s);
    44      uint offset() const
    45      {
    46          return _offset;
    47      }
    48
    49  private:
    50      uint _offset;
    51  };
    52
    53  class RLEMap : public QMap<RLEData, uint>
    54  {
    55  public:
    56      RLEMap() : _counter(0), _offset(0) {}
    57      uint insert(const uchar *d, uint l);
    58      QVector<const RLEData *> vector();
    59      void setBaseOffset(uint o)
    60      {
    61          _offset = o;
    62      }
    63
    64  private:
    65      uint _counter;
    66      uint _offset;
    67  };
