   171  bool SGIImage::readData(QImage &img)
   172  {
   173      QRgb *c;
   174      quint32 *start = _starttab;
   175      QByteArray lguard(_xsize, 0);
   176      uchar *line = (uchar *)lguard.data();
   177      unsigned x, y;
   178
   179      if (!_rle) {
   180          _pos = _data.begin();
   240          for (x = 0; x < _xsize; x++, c++) {
   241              *c = qRgba(qRed(*c), qGreen(*c), qBlue(*c), line[x]);
   242          }
   243      }
   244
   245      return true;
   246  }
