   692  bool RGBHandler::canRead(QIODevice *device)
   693  {
   694      if (!device) {
   695          qWarning("RGBHandler::canRead() called with no device");
   696          return false;
   697      }
   698
   699      const qint64 oldPos = device->pos();
   700      const QByteArray head = device->readLine(64);
   701      int readBytes = head.size();
   702
   703      if (device->isSequential()) {
   704          while (readBytes > 0) {
   705              device->ungetChar(head[readBytes-- - 1]);
   706          }
   707
   708      } else {
   709          device->seek(oldPos);
   710      }
   711
   712      return head.size() >= 4 && head.startsWith("\x01\xda") && (head[2] == 0 || head[2] == 1) && (head[3] == 1 || head[3] == 2);
   713  }
